import socket,struct,random
def query(name, qtype):
    tid=random.randint(0,65535)
    hdr=struct.pack(">HHHHHH", tid, 0x0100, 1,0,0,0)
    q=b"".join(bytes([len(p)])+p.encode() for p in name.split("."))+b"\x00"+struct.pack(">HH",qtype,1)
    s=socket.socket(socket.AF_INET, socket.SOCK_DGRAM); s.settimeout(1.0)
    try:
        s.sendto(hdr+q,("127.0.0.11",53))
        return s.recvfrom(1024)[0]
    except Exception:
        return None
    finally: s.close()
# Try AXFR-ish? no. Try reverse lookups for 172.25.0.2 and .3 -> reveals container/service names!
for ip in ["172.25.0.2","172.25.0.3","172.25.0.4"]:
