import socket,struct,random
def query(name,qtype=1):
    tid=random.randint(0,65535)
    hdr=struct.pack(">HHHHHH",tid,0x100,1,0,0,0)
    q=b"".join(bytes([len(p)])+p.encode() for p in name.split("."))+b"\x00"+struct.pack(">HH",qtype,1)
    s=socket.socket(socket.AF_INET,socket.SOCK_DGRAM); s.settimeout(1)
    s.sendto(hdr+q,("127.0.0.11",53))
    return s.recvfrom(2048)[0]
def parseA(d):
    idx=12
    while d[idx]: idx+=d[idx]+1
    idx+=5
    ips=[]
    for _ in range(struct.unpack(">H",d[6:8])[0]):
        if d[idx]&0xC0: idx+=2
        else:
            while d[idx]: idx+=d[idx]+1
            idx+=1
        t,c,ttl,rdl=struct.unpack(">HHIH",d[idx:idx+10]); idx+=10
        if t==1: ips.append(socket.inet_ntoa(d[idx:idx+rdl]))
        idx+=rdl
    return ips
for n in ["pricing-v2.corp-154fdcc8","pricing-v2.corp-154fdcc8.internal","pricing-v2","pricing.corp-154fdcc8","commons.corp-154fdcc8"]:
